<script setup>
import { onMounted, reactive, ref } from 'vue'
import AdminLayout from '../../components/admin/AdminLayout.vue'
import { adminJson } from '../../services/adminAuth'

const settings = ref([]), banks = ref([]), error = ref(''), notice = ref(''), editingBank = ref(null)
const qrFiles = reactive({})
const qrPreviews = reactive({})
const saving = reactive({})
const bank = reactive({bank_name:'',account_name:'',account_number:'',branch_name:'',routing_number:'',swift_code:'',instructions:'',display_order:0,is_active:true})
const csrf = () => document.querySelector('meta[name="csrf-token"]')?.content ?? ''

async function load(){const d=await adminJson('/api/admin/donation-settings');settings.value=d.payment_settings;banks.value=d.bank_accounts}
function selectQr(item,event){const file=event.target.files?.[0];if(!file)return;qrFiles[item.id]=file;if(qrPreviews[item.id])URL.revokeObjectURL(qrPreviews[item.id]);qrPreviews[item.id]=URL.createObjectURL(file)}
async function savePayment(item, removeQr=false){error.value='';notice.value='';saving[item.id]=true;const data=new FormData();data.append('number',item.number??'');data.append('account_type',item.account_type??'');data.append('instructions',item.instructions??'');data.append('is_active',item.is_active?'1':'0');if(qrFiles[item.id])data.append('qr_code',qrFiles[item.id]);if(removeQr)data.append('remove_qr','1');try{const r=await fetch(`/api/admin/payment-settings/${item.id}`,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf()},body:data});const json=await r.json();if(!r.ok)throw new Error(Object.values(json.errors??{}).flat()[0]??json.message);Object.assign(item,json);delete qrFiles[item.id];if(qrPreviews[item.id]){URL.revokeObjectURL(qrPreviews[item.id]);delete qrPreviews[item.id]}notice.value=`${item.method==='bkash'?'bKash':'Nagad'} তথ্য সংরক্ষণ হয়েছে।`}catch(e){error.value=e.message}finally{saving[item.id]=false}}
function editBank(i){editingBank.value=i.id;Object.assign(bank,i)}function resetBank(){editingBank.value=null;Object.assign(bank,{bank_name:'',account_name:'',account_number:'',branch_name:'',routing_number:'',swift_code:'',instructions:'',display_order:banks.value.length,is_active:true})}
async function saveBank(){try{await adminJson(editingBank.value?`/api/admin/bank-accounts/${editingBank.value}`:'/api/admin/bank-accounts',{method:editingBank.value?'PUT':'POST',body:JSON.stringify(bank)});resetBank();await load()}catch(e){error.value=e.message}}
async function removeBank(i){if(confirm('ব্যাংক অ্যাকাউন্ট মুছে ফেলবেন?')){try{await adminJson(`/api/admin/bank-accounts/${i.id}`,{method:'DELETE'});await load()}catch(e){error.value=e.message}}}
onMounted(load)
</script>

<template><AdminLayout><div class="admin-title"><div><p>পেমেন্ট ব্যবস্থাপনা</p><h1>দান সেটিংস</h1></div></div><p v-if="notice" class="success-message">{{notice}}</p><p v-if="error" class="login-error">{{error}}</p><div class="payment-settings-grid"><section v-for="item in settings" :key="item.id" class="panel payment-setting-card"><div class="panel-head"><div><h2>{{item.method==='bkash'?'bKash':'Nagad'}}</h2><p>মোবাইল পেমেন্ট ও QR তথ্য</p></div><label class="switch"><input v-model="item.is_active" type="checkbox"><span></span></label></div><form class="management-form" @submit.prevent="savePayment(item)"><label>নম্বর<input v-model="item.number" placeholder="01XXXXXXXXX"></label><label>অ্যাকাউন্ট ধরন<input v-model="item.account_type" placeholder="Personal / Merchant"></label><div class="qr-upload-block"><div class="qr-preview"><img v-if="qrPreviews[item.id]||item.qr_code_url" :src="qrPreviews[item.id]||item.qr_code_url" :alt="`${item.method} QR code`"><span v-else>QR</span></div><div><b>{{item.method==='bkash'?'bKash':'Nagad'}} QR কোড</b><p>JPG, PNG অথবা WEBP · সর্বোচ্চ 4 MB</p><label class="file-button">ছবি নির্বাচন করুন<input type="file" accept="image/jpeg,image/png,image/webp" @change="selectQr(item,$event)"></label><button v-if="item.qr_code_url" type="button" class="remove-qr" @click="savePayment(item,true)">বর্তমান QR মুছুন</button></div></div><label>নির্দেশনা<textarea v-model="item.instructions" rows="3"></textarea></label><button class="admin-button" :disabled="saving[item.id]">{{saving[item.id]?'সংরক্ষণ হচ্ছে…':'সব তথ্য সংরক্ষণ করুন'}}</button></form></section></div><div class="management-grid bank-grid"><section class="panel"><div class="panel-head"><h2>ব্যাংক অ্যাকাউন্টসমূহ</h2></div><div class="record-list"><article v-for="item in banks" :key="item.id"><div><b>{{item.bank_name}}</b><small>{{item.account_name}} · {{item.account_number}}</small></div><span class="status-pill" :class="item.is_active?'confirmed':'rejected'">{{item.is_active?'সক্রিয়':'নিষ্ক্রিয়'}}</span><button @click="editBank(item)">সম্পাদনা</button><button class="danger-text" @click="removeBank(item)">মুছুন</button></article><div v-if="!banks.length" class="empty compact">কোনো ব্যাংক অ্যাকাউন্ট নেই।</div></div></section><section class="panel sticky-panel"><div class="panel-head"><h2>{{editingBank?'ব্যাংক সম্পাদনা':'ব্যাংক যোগ করুন'}}</h2></div><form class="management-form" @submit.prevent="saveBank"><label>ব্যাংকের নাম<input v-model="bank.bank_name" required></label><label>অ্যাকাউন্ট নাম<input v-model="bank.account_name" required></label><label>অ্যাকাউন্ট নম্বর<input v-model="bank.account_number" required></label><div class="two-inputs"><label>শাখা<input v-model="bank.branch_name"></label><label>রাউটিং নম্বর<input v-model="bank.routing_number"></label></div><label>SWIFT কোড<input v-model="bank.swift_code"></label><label>নির্দেশনা<textarea v-model="bank.instructions" rows="3"></textarea></label><label class="toggle-label"><input v-model="bank.is_active" type="checkbox"> সক্রিয় রাখুন</label><button class="admin-button">সংরক্ষণ করুন</button><button v-if="editingBank" type="button" class="secondary-button" @click="resetBank">বাতিল</button></form></section></div></AdminLayout></template>
